<template>
  <div class="page-heading"><div><h1 class="page-title">推广数据{{ title }}</h1><p>{{ description }}；无可比基数时显示“—”。</p></div><div class="summary-actions"><el-select v-model="accountId" clearable placeholder="全部推广账户" class="account-picker"><el-option v-for="a in accountOptions" :key="a.key" :label="a.label" :value="a.key" /></el-select><el-date-picker v-if="props.mode === 'week'" v-model="dateRange" class="week-range-picker" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" :clearable="false" /><el-date-picker v-else v-model="monthDate" class="month-picker" type="month" value-format="YYYY-MM-DD" :clearable="false" @change="selectMonth" /><PromotionDateShortcuts :mode="props.mode" :model-value="dateRange" @select="selectQuickRange" /><el-button type="primary" :loading="loading" @click="load">查询</el-button></div></div>
  <div class="content-panel"><p class="mobile-scroll-hint">左右滑动查看完整统计</p><div class="table-wrap" v-loading="loading"><table class="summary-table" :class="`summary-table--${props.mode}`" :style="{ minWidth: tableMinWidth }"><colgroup><col class="period-column"><col class="account-column"><col v-for="field in orderedColumns" :key="field.id" class="metric-column" :style="{ width: `${fieldMinWidth(field)}px` }"></colgroup><thead><tr><th>{{ title }}</th><th>账户</th><th v-for="field in orderedColumns" :key="field.id">{{ field.label }}</th></tr></thead><tbody><template v-for="row in rows" :key="`${row.periodStart}-${row.account.id}`"><tr><td class="period-cell"><template v-if="props.mode === 'week'"><span class="period-line">{{ row.periodStart }}</span><span class="period-line">至 {{ row.periodEnd }}</span></template><template v-else>{{ row.periodLabel }}</template></td><td>{{ row.account.name }}</td><td v-for="field in orderedColumns" :key="field.id">{{ field.source === 'CUSTOM' ? customDisplay(row, field) : display(row, field.key as ColumnKey) }}</td></tr><tr class="comparison-row"><td colspan="2">同比</td><td v-for="field in orderedColumns" :key="field.id">{{ field.source === 'CUSTOM' ? customComparison(row, field) : comparison(row, field.key as ColumnKey) }}</td></tr></template><template v-if="rows.length"><tr class="total-row"><td colspan="2">合计</td><td v-for="field in orderedColumns" :key="field.id">{{ field.source === 'CUSTOM' ? customDisplay(total, field) : display(total, field.key as ColumnKey) }}</td></tr><tr class="total-comparison-row"><td colspan="2">合计同比</td><td v-for="field in orderedColumns" :key="field.id">{{ field.source === 'CUSTOM' ? customComparison(total, field) : comparison(total, field.key as ColumnKey) }}</td></tr></template><tr v-if="!rows.length"><td :colspan="orderedColumns.length + 2" class="empty">暂无数据</td></tr></tbody></table></div></div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { getPromotionAccounts, getPromotionMetricFields, getPromotionMonthly, getPromotionWeekly, type PromotionAccountItem, type PromotionMetricFieldItem, type PromotionSummaryItem } from '../api/admin';
import PromotionDateShortcuts from '../components/PromotionDateShortcuts.vue';
import { customMetricDisplay, promotionAccountKey } from '../utils/promotionMetrics';
const props = defineProps<{ mode: 'week' | 'month' }>();
const title = props.mode === 'week' ? '周统计' : '月统计'; const description = props.mode === 'week' ? '按当前选择的完整时间周期汇总，同比自动取前一相同天数周期' : '按每月 1 日至月末的自然月汇总';
const dateString = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
const currentRange = () => { const start = new Date(); if (props.mode === 'week') { start.setDate(start.getDate() - ((start.getDay() + 6) % 7)); const end = new Date(start); end.setDate(end.getDate() + 6); return [dateString(start), dateString(end)]; } start.setDate(1); const end = new Date(start.getFullYear(), start.getMonth() + 1, 0); return [dateString(start), dateString(end)]; };
const accounts = ref<PromotionAccountItem[]>([]); const fields = ref<PromotionMetricFieldItem[]>([]); const rows = ref<PromotionSummaryItem[]>([]); const loading = ref(false); const accountId = ref(''); const dateRange = ref<string[]>(currentRange()); const monthDate = ref(dateRange.value[0]);
const accountOptions = computed(() => [...new Map(accounts.value.map((account) => [promotionAccountKey(account), account])).entries()].map(([key, account]) => ({ key, label: `${account.project} · ${account.platform} · ${account.name}` })));
const columns = [{ key: 'spend', label: '消费', type: 'number' }, { key: 'impressions', label: '展现', type: 'integer' }, { key: 'clicks', label: '点击', type: 'integer' }, { key: 'clickRate', label: '点击率', type: 'rate' }, { key: 'leads', label: '总表单', type: 'integer' }, { key: 'validLeads', label: '有效表单', type: 'integer' }, { key: 'validRate', label: '有效率', type: 'rate' }, { key: 'averageCost', label: '平均成本', type: 'number' }, { key: 'validCost', label: '有效成本', type: 'number' }, { key: 'appointments', label: '到院', type: 'integer' }, { key: 'transactions', label: '成交', type: 'integer' }, { key: 'transactionAmount', label: '成交金额', type: 'number' }, { key: 'conversionRate', label: '成交率', type: 'rate' }, { key: 'arrivalRate', label: '到诊率', type: 'rate' }, { key: 'validArrivalRate', label: '有效到诊率', type: 'rate' }, { key: 'arrivalCost', label: '到院成本', type: 'number' }, { key: 'revenue', label: '实收', type: 'number' }, { key: 'roi', label: '投产比', type: 'number' }] as const;
type ColumnKey = typeof columns[number]['key'];
const orderedColumns = computed(() => fields.value.filter((field) => field.isVisible && (field.source === 'CUSTOM' || columns.some((column) => column.key === field.key))).sort((a, b) => a.sort - b.sort || a.key.localeCompare(b.key)));
const fieldMinWidth = (field: PromotionMetricFieldItem) => {
  if (['spend', 'averageCost', 'validCost', 'arrivalCost', 'transactionAmount', 'revenue', 'roi'].includes(field.key)) return 58;
  if (field.key.endsWith('Rate') || field.label.endsWith('率')) return 48;
  if (field.source === 'CUSTOM') return Math.min(68, Math.max(44, field.label.length * 10));
  return 44;
};
const tableMinWidth = computed(() => `${Math.max(850, (props.mode === 'week' ? 172 : 152) + orderedColumns.value.reduce((total, field) => total + fieldMinWidth(field), 0))}px`);
const customDisplay = (row: PromotionSummaryItem, field: PromotionMetricFieldItem) => customMetricDisplay(row.leads, row.customMetrics, field, fields.value);
const customComparison = (row: PromotionSummaryItem, field: PromotionMetricFieldItem) => {
  if (!row.previous || field.dataType !== 'NUMBER') return '—';
  const numericValue = (item: PromotionSummaryItem) => field.label.trim() === '咨询留资率'
    ? Number(String(customDisplay(item, field)).replace('%', ''))
    : Number(item.customMetrics?.[field.key]);
  const current = numericValue(row);
  const previous = numericValue(row.previous as PromotionSummaryItem);
  if (!Number.isFinite(current) || !Number.isFinite(previous) || previous === 0) return '—';
  const change = (current - previous) / Math.abs(previous) * 100;
  return `${change > 0 ? '+' : ''}${change.toFixed(0)}%`;
};
const fieldLabel = (key: string, fallback: string) => fields.value.find((field) => field.key === key)?.label || fallback;
const value = (row: PromotionSummaryItem, key: ColumnKey): number | null => key in row.calculated ? row.calculated[key as keyof typeof row.calculated] : Number(row[key as keyof PromotionSummaryItem]);
const display = (row: PromotionSummaryItem, key: ColumnKey) => { const column = columns.find((item) => item.key === key)!; const result = value(row, key); if (result === null || !Number.isFinite(result)) return '—'; if (column.type === 'rate') return `${(result * 100).toFixed(0)}%`; if (column.type === 'integer') return String(result); return result.toFixed(2); };
const comparison = (row: PromotionSummaryItem, key: ColumnKey) => { if (!row.previous) return '—'; const current = value(row, key); const previous = value(row.previous as PromotionSummaryItem, key); if (current === null || previous === null || !Number.isFinite(current) || !Number.isFinite(previous) || previous === 0) return '—'; const result = (current - previous) / Math.abs(previous) * 100; return `${result > 0 ? '+' : ''}${result.toFixed(0)}%`; };
const aggregate = (source: PromotionSummaryItem[]): PromotionSummaryItem => { const add = (key: keyof PromotionSummaryItem) => source.reduce((sum, row) => sum + Number(row[key] || 0), 0); const base: any = { periodLabel: '合计', periodStart: '', periodEnd: '', account: { id: 'total', name: '合计', platform: '' }, days: add('days'), spend: add('spend'), impressions: add('impressions'), clicks: add('clicks'), leads: add('leads'), validLeads: add('validLeads'), appointments: add('appointments'), transactions: add('transactions'), transactionAmount: add('transactionAmount'), revenue: add('revenue'), customMetrics: Object.fromEntries(fields.value.filter((field) => field.source === 'CUSTOM' && field.dataType === 'NUMBER').map((field) => [field.key, source.reduce((sum,row) => sum + Number(row.customMetrics?.[field.key] || 0), 0)])) }; const calculated = (row: any) => ({ clickRate: row.impressions ? row.clicks / row.impressions : null, validRate: row.leads ? row.validLeads / row.leads : null, averageCost: row.leads ? row.spend / row.leads : null, validCost: row.validLeads ? row.spend / row.validLeads : null, conversionRate: row.appointments ? row.transactions / row.appointments : null, arrivalRate: row.leads ? row.appointments / row.leads : null, validArrivalRate: row.validLeads ? row.appointments / row.validLeads : null, arrivalCost: row.appointments ? row.spend / row.appointments : null, roi: row.spend ? row.revenue / row.spend : null }); const previous = source.filter((row) => row.previous).map((row) => row.previous as PromotionSummaryItem); const previousBase = previous.length ? aggregate(previous) : null; return { ...base, calculated: calculated(base), previous: previousBase } as PromotionSummaryItem; };
const total = computed(() => aggregate(rows.value));
async function load() { loading.value = true; try { const [project, platform, accountName] = accountId.value ? JSON.parse(accountId.value) as string[] : ['', '', '']; const params = { accountName, project, platform, dateFrom: dateRange.value?.[0] || '', dateTo: dateRange.value?.[1] || '' }; rows.value = props.mode === 'week' ? await getPromotionWeekly(params) : await getPromotionMonthly(params); } finally { loading.value = false; } }
function monthRange(value: string): [string, string] { const [year, month] = value.split('-').map(Number); const start = new Date(year, month - 1, 1); const end = new Date(year, month, 0); return [dateString(start), dateString(end)]; }
function selectMonth(value: string) { if (value) dateRange.value = monthRange(value); }
async function selectQuickRange(value: [string, string]) { dateRange.value = value; if (props.mode === 'month') monthDate.value = value[0]; await load(); }
onMounted(() => { void Promise.allSettled([getPromotionAccounts().then((items) => { accounts.value = items; }), getPromotionMetricFields().then((items) => { fields.value = items; }), load()]); });
</script>

<style scoped>.page-heading { margin-bottom:20px; }.page-title { margin:0 0 6px; }.page-heading p { margin:0; color:var(--admin-text-muted); }.summary-actions{display:flex;flex:0 0 auto;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap}.account-picker{width:190px}.week-range-picker{width:350px!important;flex:0 0 350px}.month-picker{width:168px!important;flex:0 0 168px}.table-wrap { width:100%; overflow-x:auto; }.summary-table { width:max-content; min-width:100%; table-layout:auto; border-collapse:collapse; color:var(--el-text-color-regular); font-size:12px; text-align:center; }.summary-table .period-column{width:9%}.summary-table .account-column{width:9%}.summary-table--week .period-column{width:15%}.summary-table--week .account-column{width:8%}.summary-table th,.summary-table td { min-width:90px; padding:clamp(3px,.45vw,7px) clamp(1px,.3vw,5px); border:1px solid var(--admin-border); background:#fff; white-space:normal; overflow-wrap:anywhere; word-break:break-word; }.summary-table .period-cell{min-width:170px;white-space:nowrap;word-break:normal;font-variant-numeric:tabular-nums}.summary-table th { background:var(--el-fill-color-light); color:var(--admin-text); font-weight:650; }.summary-table tbody tr:hover td { background:var(--el-color-primary-light-9); }.summary-table .comparison-row td { color:var(--el-text-color-regular); background:var(--el-fill-color-light); }.summary-table .comparison-row td:first-child { font-weight:650; }.summary-table .total-row td { background:var(--el-color-primary-light-9); font-weight:700; }.summary-table .total-comparison-row td { color:var(--admin-text); background:var(--el-color-primary-light-8); font-weight:650; }.empty { padding:32px !important; color:var(--admin-text-muted); }@media(max-width:1250px){.page-heading{flex-direction:column}.summary-actions{width:100%;justify-content:flex-start}}@media(max-width:900px){.content-panel{padding:8px}.summary-table{font-size:12px}.summary-table th,.summary-table td{padding:5px 7px}.summary-table--week .period-column{width:16%}.summary-table--week .account-column{width:7%}}@media(max-width:760px){.summary-actions{display:grid;grid-template-columns:1fr 1fr}.account-picker,.week-range-picker,.month-picker{width:100%!important;grid-column:1/-1;flex:auto}.summary-actions :deep(.el-button){width:100%;margin:0}}
.mobile-scroll-hint { display: none; }
@media (max-width: 1024px) {
  .mobile-scroll-hint { display: block; margin: 0 0 8px; color: var(--admin-text-muted); font-size: 12px; }
  .table-wrap { overflow-x: auto; overflow-y: hidden; -webkit-overflow-scrolling: touch; scrollbar-width: thin; }
  .summary-table { width: max-content; min-width: 100%; font-size: 11px; }
  .summary-table th, .summary-table td { padding: 2px 3px; white-space: normal; overflow-wrap: anywhere; word-break: normal; line-height: 1.2; }
  .summary-table .period-cell { min-width: 108px; }
}
@media (min-width: 1025px) {
  .summary-table { width: 100%; table-layout: fixed; font-size: 11px; font-variant-numeric: tabular-nums; }
  .summary-table .period-column { width: 88px; }
  .summary-table--week .period-column { width: 108px; }
  .summary-table .account-column, .summary-table--week .account-column { width: 64px; }
  .summary-table th, .summary-table td { min-width: 0; height: 32px; padding: 2px 2px; line-height: 1.2; overflow-wrap: anywhere; }
  .summary-table .period-cell { min-width: 0; white-space: normal; overflow-wrap: normal; }
}
.summary-table th { height: 32px; color: var(--admin-text-secondary); }
.summary-table td { height: 34px; }
.period-line { display: block; white-space: nowrap; }
.table-wrap{border:1px solid var(--admin-border);border-radius:10px}
.summary-table{border:0}.summary-table thead tr:first-child th:first-child{border-top-left-radius:9px}.summary-table thead tr:first-child th:last-child{border-top-right-radius:9px}
</style>
